CREATE POLICY "admins add built-in catalog items" ON "catalog_items" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK ("catalog_items"."owner" is null and exists (select 1 from catalogs c where c.id = "catalog_items"."catalog_id" and c.owner is null) and (select public.is_admin()));--> statement-breakpoint
