CREATE POLICY "admins add built-in catalogs" ON "catalogs" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK ("catalogs"."owner" is null and (select public.is_admin()));--> statement-breakpoint
CREATE POLICY "admins change built-in catalogs" ON "catalogs" AS PERMISSIVE FOR UPDATE TO "authenticated" USING ("catalogs"."owner" is null and (select public.is_admin())) WITH CHECK ("catalogs"."owner" is null and (select public.is_admin()));--> statement-breakpoint
CREATE POLICY "admins delete built-in catalogs" ON "catalogs" AS PERMISSIVE FOR DELETE TO "authenticated" USING ("catalogs"."owner" is null and (select public.is_admin()));--> statement-breakpoint
