ALTER POLICY "change own catalog items" ON "catalog_items" TO authenticated USING ("catalog_items"."owner" = (select auth.uid())) WITH CHECK ("catalog_items"."owner" = (select auth.uid()) and exists (select 1 from catalogs c where c.id = "catalog_items"."catalog_id" and c.owner = (select auth.uid())) and (select public.has_account()));--> statement-breakpoint
